style.css:
@-moz-document domain("roblox.com") {
body, .container, .game-container, .content, .rbx-body {
    background-image: url("https://imgur.com/a/5dlA0WT");
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    background-repeat: no-repeat;
    background-color: #2b0036 !important; /* Morado oscuro base */
  }

  /* Hace los cuadros de Roblox un poco transparentes para que se vea el fondo */
  .rbx-page, .container-main, .content, .section-content, .game-card-container, .profile-container {
    background-color: rgba(25, 0, 30, 0.7) !important;
    backdrop-filter: blur(3px);
  }

  /* Cambiar texto a un color que combine */
  * {
    color: #e4c2ff !important; /* Color lavanda claro */
  }

  /* Opcional: efecto glow para títulos */
  h1, h2, h3, .text-lead, .game-name {
    text-shadow: 0 0 8px rgba(215, 140, 255, 0.8);
  }
}
